# RT TASK-20260925-2333ea: toy cell, labellers, certificates and v2 routing.
import random
from lib import *

def ord_mod(a, n):
    k, x = 1, a % n
    while x != 1: x = x * a % n; k += 1
    return k

def phi_factors(n):
    d = ord_mod(2, n)
    phi = (1 << n) - 1  # 1 + X + ... + X^(n-1)
    facs = []; rest = phi
    for f in range(1 << d, 1 << (d + 1)):
        if f & 1 and pdivmod(rest, f)[1] == 0 and irreducible(f):
            facs.append(f); rest = pdivmod(rest, f)[0]
    assert rest == 1, (n, facs)
    return sorted(facs), d

def kernel_of_g(F, g):
    n = F.n
    def L(x):
        s = 0; t = x
        for i in range(pdeg(g) + 1):
            if (g >> i) & 1: s ^= t
            t = F.sq(t)
        return s
    # columns L(z^i); kernel over F_2 by elimination on augmented rows
    rows = [(L(1 << i), 1 << i) for i in range(n)]
    basis = []; piv_rows = []
    for v, tag in rows:
        for pv, pt in piv_rows:
            if v ^ pv < v: v ^= pv; tag ^= pt
        if v == 0: basis.append(tag)
        else:
            piv_rows.append((v, tag)); piv_rows.sort(key=lambda t: -t[0])
    # re-reduce basis to be safe
    W = {0}
    for b in basis: W |= {w ^ b for w in W}
    for w in W: assert L(w) == 0
    return sorted(W), len(basis)

class Cell:
    def __init__(self, n, a, a6=1, gidx=0, M=None, log=None):
        self.n, self.a = n, a
        self.F = F = GF(n, M)
        self.E = E = Curve(F, a, a6)
        self.t = 1 if a == 1 else -1
        self.order = lucas_order(n, self.t)
        self.fac = factorint(self.order)
        self.r = r = max(self.fac); self.h = h = self.order // r
        self.k = n
        self.proj = h * pow(h, -1, r)
        rng = random.Random(subseed("P0-%d-%d" % (n, a)))
        while True:
            x = rng.randrange(2, 1 << n); pts = E.points_at_x(x)
            if pts:
                P0 = E.mul(h, pts[0])
                if P0 is not None: break
        assert E.mul(r, P0) is None
        self.P0 = P0
        s = sqrt_mod(self.t * self.t - 8, r); i2 = pow(2, -1, r)
        self.lam_cands = sorted({(self.t + s) * i2 % r, (self.t - s) * i2 % r})
        tP0 = E.frob(P0)
        self.lam = next(c for c in self.lam_cands if E.mul(c, P0) == tP0)
        lam = self.lam
        self.AR2 = {"lambda^k=1": pow(lam, n, r) == 1, "lambda!=1": lam != 1,
                    "k|r-1": (r - 1) % n == 0}
        self.mu = [pow(lam, i, r) for i in range(n)]
        self.facs, self.d = phi_factors(n)
        f1, f2 = self.facs[0], self.facs[1]
        self.divisors = [f1, f2, pmul(3, f1), pmul(3, f2)]
        self.g = self.divisors[gidx]
        self.W, self.dimW = kernel_of_g(F, self.g)
        self.build_base()
        self.cache_mul = {}

    def piG(self, P):
        return self.E.mul(self.proj, P)

    def build_base(self):
        E, F, n = self.E, self.F, self.n
        self.FW = []; self.piGmap = {}
        for x in self.W:
            if x in (0, 1): continue
            for P in E.points_at_x(x):
                Q = self.piG(P)
                if Q is not None:
                    self.FW.append(P); self.piGmap[P] = Q
        self.FWset = set(self.FW)
        # class orbits: key by x(Q); orbit = {x(Q)^(2^e)}
        self.orbit_of_x = {}; self.reps = []
        for P in self.FW:
            Q = self.piGmap[P]
            if Q[0] in self.orbit_of_x: continue
            xs = [F.frob(Q[0], e) for e in range(n)]
            assert len(set(xs)) == n, "class orbit length != k (IR-7)"
            xm = min(xs); ys = self.E.points_at_x(xm)
            QO = min(ys, key=lambda p: p[1])  # m-J1-4: lesser y
            oid = len(self.reps); self.reps.append(QO)
            for xx in xs: self.orbit_of_x[xx] = oid
        # point orbits
        self.porbit = {}; self.preps = []
        for P in self.FW:
            if P in self.porbit: continue
            orb = [E.frob(P, e) for e in range(n)]
            assert len(set(orb)) == n, "point orbit length != n (IR-7)"
            PO = min(orb); oid = len(self.preps); self.preps.append(PO)
            for Q in orb: self.porbit[Q] = oid

    def smul(self, s, P):
        key = (s, P)
        if key not in self.cache_mul: self.cache_mul[key] = self.E.mul(s, P)
        return self.cache_mul[key]

    # ---- labellers: return (oid, e, eps) for the class of a leg --------
    def label(self, P, mode="correct"):
        E, n = self.E, self.n
        Q = self.piG(P) if P not in self.piGmap else self.piGmap[P]
        oid = self.orbit_of_x.get(Q[0])
        if oid is None: return None
        QO = self.reps[oid]
        if mode == "M2s-rep": QO = E.neg(QO)
        for e in range(n):
            ee = (-e) % n if mode == "M2" else e
            T = E.frob(QO, ee)
            if T == Q: lab = (oid, e, 1); break
            if T == E.neg(Q): lab = (oid, e, -1); break
        else: raise AssertionError("no label")
        if mode == "M2s-leg": lab = (lab[0], lab[1], -lab[2])
        return lab
    def plabel(self, P, mode="correct"):
        oid = self.porbit.get(P)
        if oid is None: return None
        PO = self.preps[oid]
        for e in range(self.n):
            ee = (-e) % self.n if mode == "M2" else e
            if self.E.frob(PO, ee) == P: return (oid, e, 1)
        raise AssertionError

    def orbit_polys(self, legs, mode="correct", basis="class"):
        r, n = self.r, self.n; f = {}
        for P in legs:
            lab = self.label(P, mode) if basis == "class" else self.plabel(P, mode)
            oid, e, eps = lab
            f.setdefault(oid, [0] * n)[e] = (f.setdefault(oid, [0] * n)[e] + eps) % r
        return {o: c for o, c in f.items() if any(c)}

