# RT TASK-20260925-2333ea: instruments and v2 routing (P2-2 AR-1 -> P2-2b certs -> P2-3 ranks -> P2-6).
import random
from lib import *
from cell import Cell

INSTR = {
    "CONTROL": dict(builder="curve", lab="correct", qeval="lam"),
    "M1":      dict(builder="copy",  lab="correct", qeval="lam"),
    "M2":      dict(builder="curve", lab="M2",      qeval="lam"),
    "M2s-rep": dict(builder="curve", lab="M2s-rep", qeval="lam"),
    "M2s-leg": dict(builder="curve", lab="M2s-leg", qeval="lam"),
    "M3":      dict(builder="curve", lab="correct", qeval="laminv"),
    "M4":      dict(builder="shift1", lab="correct", qeval="lam"),
}

def build_rows_legs(c, legs0, builder):
    k = c.k; out = []
    for j in range(k):
        if builder == "copy": out.append(list(legs0))
        elif builder == "shift1" and j >= 1: out.append([c.E.frob(P, j + 1) for P in legs0])
        else: out.append([c.E.frob(P, j) for P in legs0])
    return out

def shift(poly, j, k):
    return [poly[(e - j) % k] for e in range(k)]

class Readings:
    """Certificate readings. cb: 'literal' ([lambda^j] R on the full target) or 'piG'.
    cq: 'literal' (recompute f_O(lambda_AR2)) or 'ranked' (the ranked quotient row).
    cl: 'canonical' (contract Q_O) or 'instrument' (the labeller's own representative)."""
    def __init__(self, cb="literal", cq="literal", cl="canonical"):
        self.cb, self.cq, self.cl = cb, cq, cl

def rep_for(c, oid, I, rd):
    QO = c.reps[oid]
    if rd.cl == "instrument" and I["lab"] == "M2s-rep": QO = c.E.neg(QO)
    return QO

def cert_label(c, P, I, rd, which="class"):
    r = c.r
    if which == "class":
        oid, e, eps = c.label(P, I["lab"])
        lhs = c.E.mul(c.proj, P)
        rhs = c.smul(pow(c.lam, e, r), rep_for(c, oid, I, rd))
        if eps < 0: rhs = c.E.neg(rhs)
        return lhs == rhs
    else:
        lab = c.plabel(P, "M2" if I["lab"] == "M2" else "correct")
        oid, e, _ = lab
        return P == c.E.frob(c.preps[oid], e)

def quot_point(c, I):
    return c.lam if I["qeval"] == "lam" else pow(c.lam, -1, c.r)

def ranked_quot_row(c, polys, I):
    z = quot_point(c, I)
    return {o: peval(f, z, c.r) for o, f in polys.items()}

def cert_quot(c, legs0, R, I, rd):
    polys = c.orbit_polys(legs0, I["lab"])
    if rd.cq == "literal": coords = {o: peval(f, c.lam, c.r) for o, f in polys.items()}
    else: coords = ranked_quot_row(c, polys, I)
    S = None
    for o, v in coords.items():
        S = c.E.add(S, c.smul(v, rep_for(c, o, I, rd)))
    return S == c.E.mul(c.proj, R)

def cert_bind(c, legs_rows, R, I, rd):
    """returns None if pass, else the failing sub-clause"""
    E, r, k = c.E, c.r, c.k
    legs0 = legs_rows[0]
    p0 = c.orbit_polys(legs0, I["lab"])
    for j in range(1, k):
        lj = legs_rows[j]
        if lj != [E.frob(P, j) for P in legs0]: return ("legs_j != tau^j(legs_0)", j)
        sj = E.sumpts(lj); tR = E.frob(R, j)
        if sj != tR: return ("sum legs_j != tau^j(R)", j)
        if rd.cb == "literal":
            if tR != c.smul(pow(c.lam, j, r), R): return ("tau^j(R) != [lambda^j] R", j)
        else:
            if E.mul(c.proj, tR) != c.smul(pow(c.lam, j, r), E.mul(c.proj, R)): return ("piG: tau^j(R) != [lambda^j] R", j)
        for P in lj:
            if not cert_label(c, P, I, rd): return ("CERT-LABEL row j", j)
        pj = c.orbit_polys(lj, I["lab"])
        if pj != {o: shift(f, j, k) for o, f in p0.items()}: return ("curve-side row != shift", j)
    return None

def ranks(c, legs_rows, I):
    r, k = c.r, c.k
    polys_rows = [c.orbit_polys(l, I["lab"]) for l in legs_rows]
    orbs = sorted(set(o for p in polys_rows for o in p))
    raw = [sum((p.get(o, [0] * k) for o in orbs), []) for p in polys_rows]
    pp_rows = [c.orbit_polys(l, I["lab"] if I["lab"] == "M2" else "correct", "point") for l in legs_rows]
    porbs = sorted(set(o for p in pp_rows for o in p))
    rawp = [sum((p.get(o, [0] * k) for o in porbs), []) for p in pp_rows]
    z = quot_point(c, I)
    quot = [[peval(p.get(o, [0] * k), z, r) for o in orbs] for p in polys_rows]
    Z = c.kerg_roots
    kerg = [[peval(p.get(o, [0] * k), zz, r) for o in orbs for zz in Z] for p in polys_rows] if Z else None
    p0, pp0 = polys_rows[0], pp_rows[0]
    ev_raw = sum(1 for zz in c.mu if any(peval(f, zz, r) for f in p0.values()))
    ev_pt = sum(1 for zz in c.mu if any(peval(f, zz, r) for f in pp0.values()))
    ev_q = 1 if any(peval(f, c.lam, r) for f in p0.values()) else 0
    ev_kg = sum(1 for zz in Z if any(peval(f, zz, r) for f in p0.values()))
    out = {}
    for name, M, ev in (("raw_class", raw, ev_raw), ("raw_point", rawp, ev_pt), ("quotient", quot, ev_q), ("kerg", kerg, ev_kg)):
        if M is None: out[name] = (0, 0, ev); continue
        a = rank_A(M, r); b = rank_B(M, r) if a != ev else a
        out[name] = (a, b, ev)
    return out

def route_relation(c, src, legs0, R, I, rd):
    E = c.E
    # P2-2 AR-1
    if not all(P in c.FWset for P in legs0) or E.sumpts(legs0) != R or E.mul(c.proj, R) is None:
        return {"src": src, "admitted": False, "first_rule": "AR-1 (not admitted)"}
    legs_rows = build_rows_legs(c, legs0, I["builder"])
    # P2-2b in order: CERT-LABEL row 0, CERT-QUOT row 0, CERT-BIND rows 1..k-1
    for P in legs0:
        if not cert_label(c, P, I, rd): return {"src": src, "admitted": True, "first_rule": "IR-16 (CERT-LABEL row 0)"}
    if not cert_quot(c, legs0, R, I, rd): return {"src": src, "admitted": True, "first_rule": "IR-15 (CERT-QUOT row 0)"}
    fb = cert_bind(c, legs_rows, R, I, rd)
