def relations(c, key, n1=8, n3=12, n32=12, n4=6):
    E = c.E; rng = random.Random(subseed("rels-" + key)); rels = []
    for _ in range(n1):
        R = E.mul(rng.randrange(1, c.r), c.P0); seen = set()
        for P1 in c.FW:
            P2 = E.add(R, E.neg(P1))
            if P2 in c.FWset:
                pk = tuple(sorted([P1, P2]))
                if pk not in seen: seen.add(pk); rels.append(("RS-1", list(pk), R))
    for m, cnt in ((2, n3), (3, n32)):
        for _ in range(cnt):
            legs = [rng.choice(c.FW) for _ in range(m)]
            rels.append(("RS-3 m=%d" % m, legs, E.sumpts(legs)))
    for sg in (-1, 1):
        for _ in range(n4):
            P = rng.choice(c.FW); d = rng.randrange(1, c.k); P2 = E.frob(P, d)
            if sg < 0: P2 = E.neg(P2)
            rels.append(("RS-4" + ("minus" if sg < 0 else "plus"), [P, P2], E.add(P, P2)))
    return rels

def kerg_roots(c):
    ghat = [(c.g >> i) & 1 for i in range(pdeg(c.g) + 1)]
    return [z for z in c.mu if peval(ghat, z, c.r) == 0]

